package agentusageview

import (
	"bytes"
	"os"
	"testing"

	tea "charm.land/bubbletea/v2"
)

// Live updates, step 5 (DEVDESK-45, DEVDESK-79): the view stops its chain when
// the router leaves it and picks it up again when Init resumes it. The router
// calls Leave through app.LeavingView from switchView and switchContext, and
// never when the view already on screen is named again.

// leaver is app.LeavingView, restated here: internal/app imports this package.
type leaver interface {
	Leave() (tea.Model, tea.Cmd, bool)
}

// leave calls Leave the way the router does and returns the settled view. A
// view without the method fails the test where it is used, not at compile time.
func leave(t *testing.T, m Model) (Model, tea.Cmd, bool) {
	t.Helper()
	l, ok := tea.Model(m).(leaver)
	if !ok {
		t.Fatal("Model must implement Leave() (tea.Model, tea.Cmd, bool)")
	}
	settled, cmd, allowed := l.Leave()
	next, ok := settled.(Model)
	if !ok {
		t.Fatalf("Leave returned %T, want agentusageview.Model", settled)
	}
	return next, cmd, allowed
}

// resumed delivers agentsResumeMsg and returns the model and the Cmd.
func resumed(t *testing.T, m Model) (Model, tea.Cmd) {
	t.Helper()
	updated, cmd := m.Update(agentsResumeMsg{})
	return updated.(Model), cmd
}

func TestLeaveAtTheAgentsLevelStopsTheChainAndNeverRefuses(t *testing.T) {
	m, _ := atFixture(t)
	m, _ = pollTick(t, m, m.agentGen) // a read is now in flight
	if !m.reading {
		t.Fatal("precondition: a read is in flight")
	}
	gen := m.agentGen

	left, cmd, ok := leave(t, m)

	if !ok {
		t.Error("Leave must never refuse")
	}
	if cmd != nil {
		t.Errorf("Leave has nothing to say, got a Cmd")
	}
	if left.agentGen != gen+1 {
		t.Errorf("agentGen = %d, want %d", left.agentGen, gen+1)
	}
	if left.reading || left.fullPending {
		t.Errorf("a lost read must not block anything: reading=%t fullPending=%t", left.reading, left.fullPending)
	}
	if left.level != levelAgents || left.agg == nil {
		t.Error("Leave keeps the open session: coming back finds it")
	}
}

func TestAnythingOfTheGenerationLeftBehindIsIgnoredAfterLeave(t *testing.T) {
	m, parent := atFixture(t)
	appendLine(t, parent, usageLine("msg_away", "model-alpha", 1, 7))
	m, msgs := pollTick(t, m, m.agentGen)
	reads := usageMsgs(msgs)
	if len(reads) != 1 {
		t.Fatalf("precondition: one read in flight, got %+v", msgs)
	}
	stale := m.agentGen
	before := mainOutput(t, m)

	left, _, _ := leave(t, m)

	next, out := answered(t, left, reads[0])
	if len(out) != 0 || mainOutput(t, next) != before {
		t.Errorf("an answer of gen %d must be dropped, got %+v", stale, out)
	}
	if _, out := pollTick(t, left, stale); len(out) != 0 {
		t.Errorf("a tick of gen %d must be dropped, got %+v", stale, out)
	}
}

func TestLeaveAtTheSessionsLevelChangesNothing(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl")

	left, cmd, ok := leave(t, m)

	if !ok || cmd != nil {
		t.Errorf("ok=%t cmd=%v, want true and no Cmd", ok, cmd != nil)
	}
	if left.agentGen != m.agentGen || left.gen != m.gen || left.level != levelSessions {
		t.Error("the sessions level has no chain: nothing to bump")
	}
}

// The review scenario: a read lost with the view must not leave ctrl+r waiting
// for an answer that will never come.
func TestCtrlRStartsAReadAfterTheViewWasLeftWhileOneWasInFlight(t *testing.T) {
	m, _, cmd := openedFixture(t)
	_ = cmd // the open's answer never arrives: the view was left first
	if !m.reading {
		t.Fatal("precondition: the open's read is in flight")
	}
	m, _, _ = leave(t, m)

	m, cmd = opened(t, m, "ctrl+r")

	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || !reads[0].delta.Full() || reads[0].gen != m.agentGen {
		t.Fatalf("ctrl+r must start one full read of the current gen, got %+v", reads)
	}
	if m.fullPending {
		t.Error("nothing was in flight to wait for: no pending full read")
	}
}

// The plan keeps a ctrl+r typed before Leave: the resume turns it into a full
// read, so the refresh the user asked for is not lost.
func TestACtrlRWaitingOnALostReadIsKeptByLeaveAndResumesAsAFullRead(t *testing.T) {
	m, _, _ := openedFixture(t)
	m, _ = opened(t, m, "ctrl+r") // read in flight: the full read is queued
	if !m.fullPending {
		t.Fatal("precondition: ctrl+r is queued behind the read")
	}

	left, _, _ := leave(t, m)

	if !left.fullPending || left.reading {
		t.Errorf("reading=%t fullPending=%t, want false and true", left.reading, left.fullPending)
	}
	if left.agentsLoading {
		t.Error("no read is in flight: the footer must not keep a loading status")
	}
	back, cmd := resumed(t, left)
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || !reads[0].delta.Full() {
		t.Fatalf("the resume must start one full read, got %+v", reads)
	}
	if back.fullPending {
		t.Error("the full read consumed the pending refresh")
	}
	if !back.agentsLoading {
		t.Error("a resumed full read shows its spinner")
	}
}

// rewriteSameSize changes the orchestrator's last output count without moving
// the size or the mtime, which an incremental read cannot see (DEVDESK-44 D4).
func rewriteSameSize(t *testing.T, parent string) {
	t.Helper()
	info, err := os.Stat(parent)
	if err != nil {
		t.Fatal(err)
	}
	raw, err := os.ReadFile(parent)
	if err != nil {
		t.Fatal(err)
	}
	edited := bytes.Replace(raw, []byte(`"output_tokens":120`), []byte(`"output_tokens":121`), 1)
	if bytes.Equal(edited, raw) || len(edited) != len(raw) {
		t.Fatal("the fixture no longer holds the expected token count")
	}
	if err := os.WriteFile(parent, edited, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Chtimes(parent, info.ModTime(), info.ModTime()); err != nil {
		t.Fatal(err)
	}
}

// A ctrl+r with no read in flight starts a full read at once, so nothing is
// pending; leaving before its answer must not turn it into an incremental read
// on return, or a same-size rewrite stays invisible.
func TestACtrlRInFlightWhenTheViewIsLeftResumesAsAFullRead(t *testing.T) {
	m, parent := atFixture(t)
	before := mainOutput(t, m)
	rewriteSameSize(t, parent)
	m, _ = opened(t, m, "ctrl+r") // full read in flight; its answer never arrives
	if !m.reading || !m.agentsLoading || m.fullPending {
		t.Fatalf("precondition: reading=%t loading=%t pending=%t", m.reading, m.agentsLoading, m.fullPending)
	}
	m, _, _ = leave(t, m)

	m, cmd := resumed(t, m)

	if !m.agentsLoading {
		t.Error("the resumed full read shows its spinner")
	}
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || !reads[0].delta.Full() {
		t.Fatalf("the resume must start one full read, got %+v", reads)
	}
	m, _ = answered(t, m, reads[0])
	if after := mainOutput(t, m); after == before {
		t.Errorf("output still %d: the same-size rewrite stayed invisible", after)
	}
	if m.agentsLoading || m.reading {
		t.Error("the answer ends the full read")
	}
}

// The open's first read is full (fresh cursor) and shows a spinner; leaving
// before its answer must keep both on return.
func TestAnOpenLeftBeforeItsFirstAnswerResumesWithAFullReadAndASpinner(t *testing.T) {
	m, _, _ := openedFixture(t)
	if !m.reading || !m.agentsLoading {
		t.Fatal("precondition: the open's read is in flight with its spinner")
	}
	m, _, _ = leave(t, m)

	m, cmd := resumed(t, m)

	if !m.agentsLoading {
		t.Error("the table is empty until the answer: the spinner must show")
	}
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || !reads[0].delta.Full() {
		t.Fatalf("the resume must start one full read, got %+v", reads)
	}
	m, _ = answered(t, m, reads[0])
	if m.agentsLoading || len(m.usage.Agents) == 0 {
		t.Errorf("loading=%t agents=%d, want rows and no spinner", m.agentsLoading, len(m.usage.Agents))
	}
}

func TestResumeReadsWhatChangedWhileAwayWithoutASpinner(t *testing.T) {
	m, parent := atFixture(t)
	before := mainOutput(t, m)
	m, _, _ = leave(t, m)
	appendLine(t, parent, usageLine("msg_away", "model-alpha", 3, 41))
	gen := m.agentGen

	m, cmd := resumed(t, m)

	if m.agentGen != gen+1 {
		t.Errorf("agentGen = %d, want %d", m.agentGen, gen+1)
	}
	if m.agentsLoading {
		t.Error("a resume is silent: no spinner")
	}
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 || reads[0].delta.Full() || reads[0].gen != m.agentGen {
		t.Fatalf("want one incremental read of gen %d, got %+v", m.agentGen, reads)
	}
	m, msgs := answered(t, m, reads[0])
	if got := mainOutput(t, m); got != before+41 {
		t.Errorf("output = %d, want %d: the line written while away", got, before+41)
	}
	ticks := ticksOf(msgs)
	if len(ticks) != 1 {
		t.Fatalf("a live session goes on polling, got %+v", msgs)
	}
	if _, again := pollTick(t, m, ticks[0].gen); len(usageMsgs(again)) != 1 {
		t.Errorf("the chain must go on after the resume, got %+v", again)
	}
}

func TestResumeOutsideTheAgentsLevelDoesNothing(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl")

	next, cmd := resumed(t, m)

	if cmd != nil || next.agentGen != m.agentGen {
		t.Errorf("no session open: nothing to resume, got a Cmd=%t gen %d", cmd != nil, next.agentGen)
	}
}

// Leave, then a quick return: the tick that was pending before leaving arrives
// after the resume and must not start a second chain.
func TestAQuickReturnLeavesExactlyOneChain(t *testing.T) {
	m, _ := atFixture(t)
	oldTick := m.agentGen
	m, _, _ = leave(t, m)
	m, cmd := resumed(t, m)
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 {
		t.Fatalf("the resume starts one read, got %+v", reads)
	}

	// The old tick lands while the resume's read is in flight, and again after.
	m, msgs := pollTick(t, m, oldTick)
	if len(msgs) != 0 {
		t.Errorf("a tick of the gen before Leave must be ignored, got %+v", msgs)
	}
	m, msgs = answered(t, m, reads[0])
	if len(ticksOf(msgs)) != 1 {
		t.Fatalf("one tick follows the resume's answer, got %+v", msgs)
	}
	if _, msgs = pollTick(t, m, oldTick); len(msgs) != 0 {
		t.Errorf("the old tick is still ignored after the answer, got %+v", msgs)
	}
}

// `:au` typed again does not call Leave: the second resume must kill the chain
// the first one started.
func TestAResumeTwiceInARowKeepsTheLastChainOnly(t *testing.T) {
	m, _ := atFixture(t)
	m, first := resumed(t, m)
	firstRead := usageMsgs(batchMsgs(t, first))
	m, second := resumed(t, m)
	secondRead := usageMsgs(batchMsgs(t, second))
	if len(firstRead) != 1 || len(secondRead) != 1 {
		t.Fatalf("each resume starts a read: %+v / %+v", firstRead, secondRead)
	}

	m, msgs := answered(t, m, firstRead[0])
	if len(msgs) != 0 {
		t.Errorf("the first chain's answer must be dropped, got %+v", msgs)
	}
	if !m.reading {
		t.Error("the second chain's read is still awaited")
	}
	_, msgs = answered(t, m, secondRead[0])
	if len(ticksOf(msgs)) != 1 {
		t.Errorf("the second chain goes on, got %+v", msgs)
	}
}

func TestResumeOnASettledSessionReadsOnceThenStopsAgainIfStillQuiet(t *testing.T) {
	parent := copyFixture(t)
	finishTester(t, parent)
	ageAll(t, parent, 10*quietPeriod)
	m := withSessions(t, parent)
	m, cmd := opened(t, m, "right")
	m, msgs := answered(t, m, firstDelta(t, cmd))
	if len(msgs) != 0 {
		t.Fatalf("precondition: the chain stopped, got %+v", msgs)
	}

	m, cmd = resumed(t, m)
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 {
		t.Fatalf("a settled session is read once on resume, got %+v", reads)
	}
	_, msgs = answered(t, m, reads[0])
	if len(msgs) != 0 {
		t.Errorf("still quiet: the chain stops again, got %+v", msgs)
	}
}

func TestResumeOnASettledSessionThatGrewGoesLiveAgain(t *testing.T) {
	parent := copyFixture(t)
	finishTester(t, parent)
	ageAll(t, parent, 10*quietPeriod)
	m := withSessions(t, parent)
	m, cmd := opened(t, m, "right")
	m, _ = answered(t, m, firstDelta(t, cmd))
	m, _, _ = leave(t, m)
	appendLine(t, parent, usageLine("msg_back", "model-alpha", 1, 2))

	m, cmd = resumed(t, m)
	m, msgs := answered(t, m, firstDelta(t, cmd))

	ticks := ticksOf(msgs)
	if len(ticks) != 1 {
		t.Fatalf("a fresh write brings the chain back, got %+v", msgs)
	}
	if _, again := pollTick(t, m, ticks[0].gen); len(usageMsgs(again)) != 1 {
		t.Errorf("the tick of the revived chain must start a read, got %+v", again)
	}
}
package agentusageview

import (
	"os"
	"strings"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 6 (DEVDESK-45, DEVDESK-80): the "Updates" header slot
// (live while the chain runs, paused once it stopped) and the help text.

const updatesKey = "Updates"

// updatesValue returns the value of the Updates header entry, and whether the
// entry exists.
func updatesValue(m Model) (string, bool) {
	for _, h := range m.GetHeaderInfo("") {
		if h.Key == updatesKey {
			return h.Value, true
		}
	}
	return "", false
}

func wantUpdates(t *testing.T, name string, m Model, want string) {
	t.Helper()
	got, ok := updatesValue(m)
	if !ok {
		t.Errorf("%s: no %q header entry, want %q", name, updatesKey, want)
		return
	}
	if got != want {
		t.Errorf("%s: Updates = %q, want %q", name, got, want)
	}
}

// settledModel is a fixture session quiet for 10 minutes, its first read answered.
func settledModel(t *testing.T) (Model, string) {
	t.Helper()
	parent := copyFixture(t)
	finishTester(t, parent)
	ageAll(t, parent, 10*time.Minute)
	m := withSessions(t, parent)
	m, cmd := opened(t, m, "right")
	m, _ = answered(t, m, firstDelta(t, cmd))
	return m, parent
}

func TestHeaderSaysLiveWhileTheChainRuns(t *testing.T) {
	m, _, cmd := openedFixture(t)
	wantUpdates(t, "just opened, first read in flight", m, "live")

	m, msgs := answered(t, m, firstDelta(t, cmd))
	if len(ticksOf(msgs)) != 1 {
		t.Fatalf("precondition: an active session schedules a tick, got %+v", msgs)
	}
	wantUpdates(t, "after the answer of an active session", m, "live")

	m, _ = pollTick(t, m, m.agentGen) // a poll read is now in flight
	wantUpdates(t, "poll read in flight", m, "live")
}

func TestHeaderSaysPausedOnceTheSessionSettled(t *testing.T) {
	m, _ := settledModel(t)
	wantUpdates(t, "settled", m, "paused")
	for _, key := range []string{"Agents", "Tokens"} {
		found := false
		for _, h := range m.GetHeaderInfo("") {
			found = found || h.Key == key
		}
		if !found {
			t.Errorf("the %s entry must stay beside Updates", key)
		}
	}
}

func TestHeaderSaysPausedWhenTheTranscriptIsGone(t *testing.T) {
	m, parent := atFixture(t)
	if err := os.Remove(parent); err != nil {
		t.Fatal(err)
	}
	m, msgs := pollTick(t, m, m.agentGen)
	reads := usageMsgs(msgs)
	if len(reads) != 1 {
		t.Fatalf("precondition: one read, got %+v", msgs)
	}
	m, _ = answered(t, m, reads[0])
	wantUpdates(t, "after ErrNotExist", m, "paused")
}

func TestHeaderStaysLiveWhenAReadFailsForAnotherReason(t *testing.T) {
	m, _ := atFixture(t)
	m, msgs := pollTick(t, m, m.agentGen)
	reads := usageMsgs(msgs)
	if len(reads) != 1 {
		t.Fatalf("precondition: one read, got %+v", msgs)
	}
	reads[0].err = os.ErrPermission // retried by the chain: still live
	m, _ = answered(t, m, reads[0])
	wantUpdates(t, "after a transient failure", m, "live")
}

func TestHeaderHasNoUpdatesEntryOutsideAnOpenSession(t *testing.T) {
	states := map[string]Model{
		"sessions loading": newModel(t),
		"sessions listed":  withSessions(t, "/p/a.jsonl"),
	}
	back, _ := atFixture(t)
	back, _ = opened(t, back, "esc")
	states["back from a session"] = back
	for name, m := range states {
		if v, ok := updatesValue(m); ok {
			t.Errorf("%s: unexpected Updates entry %q at the sessions level", name, v)
		}
	}
}

func TestCtrlRBringsTheHeaderBackToLiveWhenTheSessionResumed(t *testing.T) {
	m, parent := settledModel(t)
	wantUpdates(t, "precondition", m, "paused")

	appendLine(t, parent, usageLine("msg_wake", "model-alpha", 1, 2))
	m, cmd := opened(t, m, "ctrl+r")
	m, _ = answered(t, m, firstDelta(t, cmd))
	// The fixture files were aged, but the appended line is fresh.
	wantUpdates(t, "ctrl+r on a session written to again", m, "live")
}

func TestCtrlRKeepsTheHeaderPausedWhenTheSessionIsStillQuiet(t *testing.T) {
	m, _ := settledModel(t)
	m, cmd := opened(t, m, "ctrl+r")
	m, _ = answered(t, m, firstDelta(t, cmd))
	wantUpdates(t, "ctrl+r on a quiet session", m, "paused")
}

func TestHeaderGoesLiveAgainWhenTheViewIsResumed(t *testing.T) {
	m, _ := settledModel(t)
	m, _ = resumed(t, m) // the chain restarts and a read is in flight
	wantUpdates(t, "resumed", m, "live")
}

func TestShortcutKeysDoNotChangeBetweenLivePausedLoadingAndError(t *testing.T) {
	live, _ := atFixture(t)
	paused, _ := settledModel(t)
	loading, _, _ := openedFixture(t)
	failed, _, _ := openedFixture(t)
	failed = feed(t, failed, usageDeltaMsg{gen: failed.agentGen, err: os.ErrNotExist})

	tn := time.Now()
	idle := sizedAgents(t, 120, agentusage.Usage{Agents: []agentusage.Agent{
		stamped(orchestrator(5, 0), 1, tn.Add(-time.Hour), tn),
		stamped(withState(subAgent("a01", "coder", 1, 0), agentusage.StateUnfinished), 2, tn.Add(-time.Hour), tn.Add(-20*time.Minute)),
	}}, statusClock{now: tn, alive: true})
	if got := stateOf(t, idle, "a01"); got != stateIdle {
		t.Fatalf("precondition: a01 = %s, want idle", got.label())
	}

	want := strings.Join(testutil.ShortcutKeys(live.GetShortcuts()), ",")
	breakdown := feed(t, live, testutil.Key("tab"))
	for name, m := range map[string]Model{"paused": paused, "loading": loading, "error": failed, "idle": idle, "breakdown": breakdown} {
		if got := strings.Join(testutil.ShortcutKeys(m.GetShortcuts()), ","); got != want {
			t.Errorf("%s: keys %s, want %s", name, got, want)
		}
		if !testutil.ShortcutEnabled(m.GetShortcuts(), "ctrl+r") {
			t.Errorf("%s: ctrl+r must stay enabled", name)
		}
	}
	for _, sc := range live.GetShortcuts() {
		if sc.Key == "ctrl+r" && sc.Description != "Refresh" {
			t.Errorf("ctrl+r description = %q, want Refresh", sc.Description)
		}
	}
}

func TestHelpDescribesLiveUpdates(t *testing.T) {
	c := New(nil).GetHelpContent()

	var body string
	for _, s := range c.Sections {
		if s.Title == "Live updates" {
			body = strings.ToLower(s.Body)
		}
	}
	if body == "" {
		t.Fatal(`help needs a section titled "Live updates"`)
	}
	for _, want := range []string{"2 s", "5 min", "ctrl+r", "paused", "live"} {
		if !strings.Contains(body, want) {
			t.Errorf("the Live updates section should mention %q:\n%s", want, body)
		}
	}

	found := false
	for _, b := range c.KeyBindings {
		if b.Key == "ctrl+r" {
			found = true
			if !strings.Contains(b.Description, "Re-read the whole session from the start") {
				t.Errorf("ctrl+r help = %q, want it to say \"Re-read the whole session from the start\"", b.Description)
			}
		}
	}
	if !found {
		t.Error("help lacks ctrl+r")
	}
}

func TestHeaderCountsIdleAgentsOnlyWhenThereAreSome(t *testing.T) {
	tn := time.Now()
	idle := activityUsage(tn)
	idle.Agents[1].LastActivity = tn.Add(-20 * time.Minute) // unfinished and quiet
	m := sizedAgents(t, 120, idle, statusClock{now: tn, alive: true})
	if got := headerValue(t, m, "Idle"); got != "1" {
		t.Errorf("Idle = %q, want 1", got)
	}

	calm := sizedAgents(t, 120, activityUsage(tn), statusClock{now: tn, alive: true})
	for _, h := range calm.agentsHeaderInfo() {
		if h.Key == "Idle" {
			t.Errorf("no agent is idle but the header shows Idle %s", h.Value)
		}
	}
}

func TestHelpDescribesActivity(t *testing.T) {
	var body string
	for _, s := range New(nil).GetHelpContent().Sections {
		body += strings.ToLower(s.Body) + "\n"
	}
	for _, want := range []string{"state", "tools", "duration", "idle", "5 min", "names, inputs and results are never read"} {
		if !strings.Contains(body, want) {
			t.Errorf("help should mention %q", want)
		}
	}
}
package agentusageview

import (
	"errors"
	"fmt"
	"io/fs"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/agentusage"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 4 (DEVDESK-45): the poll chain (answer, wait pollInterval,
// read, answer...) and the rule that stops it. Option A of the plan:
// quietPeriod 5 min, a settled session or a deleted transcript ends the chain.
// Leave/resume (step 5) and the header's live/paused slot (step 6) are not here.

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

// ── Helpers ──────────────────────────────────────────────────────────────────

// usageLine is one assistant transcript line for message msgID.
func usageLine(msgID, model string, in, out int) string {
	return fmt.Sprintf(`{"type":"assistant","uuid":"u-%[1]s","message":{"id":%[1]q,"model":%[2]q,"role":"assistant","stop_reason":"end_turn","content":[],"usage":{"input_tokens":%[3]d,"output_tokens":%[4]d,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}}}`,
		msgID, model, in, out)
}

// appendLine appends line and a newline to path.
func appendLine(t *testing.T, path, line string) {
	t.Helper()
	appendRaw(t, path, line+"\n")
}

func appendRaw(t *testing.T, path, s string) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o600)
	if err != nil {
		t.Error(err)
		return
	}
	defer func() {
		if err := f.Close(); err != nil {
			t.Error(err)
		}
	}()
	if _, err := f.WriteString(s); err != nil {
		t.Error(err)
	}
}

// subDir is the sub-agents directory of the copied session.
func subDir(parent string) string {
	return filepath.Join(strings.TrimSuffix(parent, ".jsonl"), "subagents")
}

// finishTester flips the fixture's one unfinished sub-agent (a02) to finished,
// so nothing keeps the session alive but the recency of its files.
func finishTester(t *testing.T, parent string) {
	t.Helper()
	p := filepath.Join(subDir(parent), "agent-a02.meta.json")
	raw, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	edited := strings.Replace(string(raw), `"finished":false`, `"finished":true`, 1)
	if edited == string(raw) {
		t.Fatal("the fixture's a02 meta no longer says finished:false")
	}
	if err := os.WriteFile(p, []byte(edited), 0o600); err != nil {
	return m, pollTickCmd(m.agentGen)
}

// handlePollTick starts the incremental read a tick asks for, unless the tick
// belongs to a superseded chain or a read is already in flight. No spinner:
// polling is silent.
func (m Model) handlePollTick(msg usagePollTickMsg) (tea.Model, tea.Cmd) {
	if msg.gen != m.agentGen || m.level != levelAgents || m.agg == nil || m.reading || m.pollStopped {
		return m, nil
	}
	return m, m.startRead(false)
}

// Leave stops the open session's chain when the router switches away: the new
// generation drops any tick or read still in flight, and nothing is awaited
// any more. The session stays open and coming back resumes it (handleResume).
// A pending ctrl+r is kept, and so is a full read lost in flight (a ctrl+r, or
// the open's first read): the resume repeats it as a full read. It never refuses.
func (m Model) Leave() (tea.Model, tea.Cmd, bool) {
	if m.level == levelAgents {
		m.agentGen++
		m.fullPending = m.fullPending || (m.reading && m.agentsLoading)
		m.reading, m.agentsLoading = false, false
	}
	return m, nil, true
}

// handleResume restarts the open session's chain under a new generation, which
// drops the answers of any earlier chain. It reads from the cursor, silently;
// a ctrl+r left pending by Leave becomes a full read, with its spinner.
func (m Model) handleResume() (tea.Model, tea.Cmd) {
	if m.level != levelAgents || m.agg == nil {
		return m, nil
	}
	m.agentGen++
	m.pollStopped = false
	if m.fullPending {
		m.fullPending = false
		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
	}
	return m, m.startRead(false)
}

// startRead marks a read in flight and returns it; full reads everything again.
func (m *Model) startRead(full bool) tea.Cmd {
	c := m.agg.Cursor()
	if full {
		c = c.Rewound()
		m.agentsLoading, m.fullPending, m.pollStopped = true, false, false
	}
	m.reading = true
	return readDeltaCmd(m.agentGen, c)
}

// handlePaste hands pasted text to the filter while it has the keyboard; with
// no field focused a paste is dropped, never read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.InEditMode() {
		return m, m.activeTable(msg)
	}
	return m, nil
}

// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
// screen, → and enter open a session, ← and esc go back.
func (m Model) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
